'use strict';

/**
 * V90Phase3 — the Phase 3 signals of ITU-T V.90 (09/98) that the digital modem
 * transmits: TRN1d, Jd, J′d and DIL, plus the DIL descriptor the analogue modem
 * sends to specify DIL. Built to the Recommendation's own bit layouts (Table
 * 12/V.90 for the descriptor, Table 13/V.90 for Jd) rather than to an invented
 * framing, the same way V90Phase4 is built to Tables 14 and 16.
 *
 * Phase 3 is equaliser/echo-canceller training and digital impairment learning:
 * the analogue modem asks, in the DIL descriptor, for a specific probe of the
 * digital modem's codeword space, and the digital modem plays it. Nothing here
 * measures anything — see "What this does not do" at the foot.
 *
 * ── The order, from §9.3.1 rather than from Figure 5 ────────────────────────
 * The figure's label layer interleaves the two modems' rows and its duration
 * marks do not attach unambiguously to a signal; §9.3.1 states the same
 * sequence in prose and is what this module follows:
 *
 *   §9.3.1.3  after receiving Ja, the digital modem may wait up to 500 ms and
 *             shall then transmit Sd for 384T and S̄d for 48T
 *   §9.3.1.4  it shall then transmit TRN1d for a MINIMUM of 2040T; within
 *             4000 ms of starting TRN1d it shall transmit Jd
 *   §9.3.1.5  it repeats Jd until it detects S, completes the current Jd, then
 *             transmits J′d. If the analogue modem requested a DIL of length
 *             zero it proceeds to Phase 4
 *   §9.3.1.6  otherwise it sends the DIL; after a subsequent S-to-S̄ transition
 *             it completes the current DIL segment and proceeds to Phase 4
 *
 * So Sd comes FIRST and TRN1d after it — not the other way round, which is the
 * reading Figure 5's left-to-right label order invites.
 *
 * ── The signals ────────────────────────────────────────────────────────────
 *
 * TRN1d (§8.4.5). "A sequence of the PCM codeword whose Ucode is U_INFO with
 * signs generated by applying binary ones to the input of the scrambler
 * described in 5.3. A sign of 0 represents a negative voltage, a sign of 1 a
 * positive voltage. The scrambler is initialized to zero prior to the
 * transmission of TRN1d. TRN1d shall be an integer multiple of 6 symbols long."
 * §5.3 is clause 7/V.34's GPC, which is the scrambler V90.js already runs.
 *
 * Jd (§8.4.2, Table 13). 72 bits, a whole number of repetitions, bit 0 first,
 * "scrambled and differentially encoded and then transmitted as the sign of the
 * PCM codeword whose Ucode is U_INFO". The differential encoder is initialized
 * with the final symbol of the transmitted TRN1d.
 *
 * J′d (§8.4.3). Twelve binary zeroes, same encoding, initialized with the final
 * symbol of the transmitted Jd. It terminates Jd.
 *
 * DIL (§8.4.1). N segments, 0 ≤ N ≤ 255. A segment carrying training symbols
 * from Uchord c is Lc = (Hc + 1) × 6 symbols long. Within a segment the Sign
 * Pattern gives each symbol's sign (0 negative, 1 positive) and the Training
 * Pattern chooses between the chord's reference codeword REFc (bit 0) and the
 * segment's training symbol (bit 1); the LSB of each pattern applies to the
 * first symbol of a segment and both patterns restart at every segment
 * boundary, repeating independently inside a segment longer than their own
 * length. The whole sequence repeats until the analogue modem terminates it,
 * always on a segment boundary. When N = 0, DIL is not transmitted.
 *
 * ── U_INFO is a negotiated value, not a constant ───────────────────────────
 * Table 10/V.90 bits 25:31: "U_INFO: Ucode of the PCM codeword to be used by
 * the digital modem for the 2 point train. The power of this point shall not
 * exceed the maximum digital modem transmit power. U_INFO shall be greater
 * than 66." §8.4.4 then defines Sd's W as the codeword whose Ucode is
 * 16 + U_INFO, which caps U_INFO at 111 for W to exist at all. So
 * 67 ≤ U_INFO ≤ 111, and uInfoValid() is that pair of bounds.
 *
 * ── What this does not do ──────────────────────────────────────────────────
 * DIL exists so the analogue modem can LEARN the digital impairments on the
 * path — robbed-bit signalling, digital pads, a-law/µ-law transcoding. On this
 * transport there are none: the samples arrive as they left. So the probe is
 * transmitted faithfully and nothing is measured from it. Built this way round,
 * a later interop receiver ADDS a measurement behind a transmitter that is
 * already real, instead of having to replace an invented one.
 */

const BF = require('./BitFrame');

const SYNC_BITS = BF.SYNC_BITS;         // 17
const GROUP = BF.GROUP;                 // 17: one start bit + 16 payload bits
const UCODES = 128;
const SYMS_PER_FRAME = 6;

// U_INFO's legal range: §8.4.4 needs 16 + U_INFO to be a Ucode, Table 10 needs
// U_INFO > 66.
const U_INFO_MIN = 67, U_INFO_MAX = UCODES - 1 - 16;   // 67 .. 111
const uInfoValid = (u) => Number.isInteger(u) && u >= U_INFO_MIN && u <= U_INFO_MAX;
/** §8.4.4: W is the PCM codeword whose Ucode is 16 + U_INFO. */
const sdWUcode = (uInfo) => 16 + uInfo;

// §9.3.1.4 — TRN1d is a MINIMUM of 2040T, and §8.4.5 requires a whole number of
// six-symbol frames. 2040 is already 340 frames, so the minimum is legal as it
// stands.
const TRN1D_MIN_SYMBOLS = 2040;

// ── Table 13/V.90 — Jd ─────────────────────────────────────────────────────
const JD_BITS = 72;
const JD_START_BITS = [17, 34, 51];
// Bits 18:33 then 35:46: "Bit 18: 28 000; bit 19: 29 333; bit 20: 30 666; …;
// bit 33: 48 000" and "bit 35: 49 333; bit 36: 50 666; …; bit 40: 56 000".
// One ladder, 4000/3 bit/s apart, split across two groups by the start bit at
// 34 — so the rate for mask index n is 28000 + n·4000/3, n = 0..21, and bits
// 41:46 are reserved rather than rates.
const JD_RATE_BASE = 28000, JD_RATE_STEP = 4000 / 3, JD_RATE_COUNT = 22;
const jdRate = (n) => Math.round(JD_RATE_BASE + n * JD_RATE_STEP);
/** Mask bit position for ladder index n: 18..33 then 35..40. */
const jdRateBit = (n) => (n < 16 ? 18 + n : 35 + (n - 16));

/**
 * Build Jd (Table 13/V.90).
 *
 * @param {object} p
 *   rates      {number[]} downstream rates supported and enabled in the digital
 *              modem's transmitter. Matched to the ladder within half a step,
 *              because the ladder is 4000/3 apart and so not all integers.
 *   cpConst    0 = 4-point, 1 = 16-point, for CP/E/SCR during training (bit 47)
 *   rrConst    the same for rate renegotiation (bit 48)
 *   lookahead  1..3, the digital modem's maximum lookahead for spectral shaping
 */
function buildJd({ rates = [], cpConst = 0, rrConst = 0, lookahead = 1 } = {}) {
  const bits = BF.newSequence(JD_BITS, JD_START_BITS);
  for (const r of rates) {
    for (let n = 0; n < JD_RATE_COUNT; n++) {
      if (Math.abs(jdRate(n) - r) <= JD_RATE_STEP / 2) bits[jdRateBit(n)] = 1;
    }
  }
  bits[47] = cpConst ? 1 : 0;
  bits[48] = rrConst ? 1 : 0;
  BF.putUInt(bits, 49, 50, Math.max(1, Math.min(3, lookahead)));
  // CRC over 52:67. Coverage is everything from the first information bit to
  // the CRC that is not a start bit — §10.1.2.3.2/V.34 as BitFrame states it.
  BF.putUInt(bits, 52, 67, BF.crcOf(bits, JD_START_BITS, SYNC_BITS, 52));
  // 68:71 fill zeroes, already zero from newSequence.
  return bits;
}

function parseJd(bits) {
  const sync = bits.slice(0, SYNC_BITS).every((b) => b === 1);
  const rates = [];
  for (let n = 0; n < JD_RATE_COUNT; n++) if (bits[jdRateBit(n)]) rates.push(jdRate(n));
  const crc = BF.getUInt(bits, 52, 67);
  const crcOk = crc === BF.crcOf(bits, JD_START_BITS, SYNC_BITS, 52);
  return {
    sync, crcOk, rates,
    cpConst: bits[47], rrConst: bits[48],
    lookahead: BF.getUInt(bits, 49, 50),
  };
}

// ── Table 12/V.90 — the DIL descriptor ─────────────────────────────────────
// The layout is variable-length: SP and TP are 1..128 bits each and are carried
// in 16-bit instalments with a start bit every 16, which is what α and β are
// for. §8.4.1: "α = ⌈L_SP/16⌉ × 17 and β = α + ⌈L_TP/16⌉ × 17, where ⌈x⌉ is the
// smallest integer higher than or equal to x. When L_SP is not a multiple of 16,
// zeroes shall be used to pad SP to the next multiple of 16 bits so that the
// format of the Ja sequence is preserved. Similarly, when L_TP is not a multiple
// of 16, zeroes shall be used to pad TP."
const dilAlpha = (lsp) => Math.ceil(lsp / 16) * GROUP;
const dilBeta = (lsp, ltp) => dilAlpha(lsp) + Math.ceil(ltp / 16) * GROUP;

/**
 * Every bit position that is a start bit, for a descriptor with these
 * parameters. Derived from the table's own rule — a start bit every 17 bits
 * from bit 17 — rather than listed, because the positions move with α, β and N.
 */
function dilStartBits(len) {
  const out = [];
  for (let p = SYNC_BITS; p + GROUP <= len + GROUP - 1; p += GROUP) out.push(p);
  return out;
}

/** Total descriptor length in bits, including the trailing fill. */
function dilLength(lsp, ltp, n) {
  const beta = dilBeta(lsp, ltp);
  // Through "204+β+⌈N/2⌉×17 Fill bit: 0" the sequence is that many bits plus one.
  const through = 205 + beta + Math.ceil(n / 2) * GROUP;
  // "205+β+⌈N/2⌉×17 Fill bit: 0 may be necessary to ensure that the descriptor
  // has an even number of bits."
  return through % 2 === 0 ? through : through + 1;
}

/**
 * Build the DIL descriptor (Table 12/V.90).
 *
 * @param {object} d
 *   n        {number}   0..255, the number of DIL-segments. 0 = no DIL.
 *   sp       {number[]} sign pattern bits, 1..128 of them
 *   tp       {number[]} training pattern bits, 1..128 of them
 *   h        {number[]} eight Hc, 0..127; segment length for chord c is (Hc+1)×6
 *   ref      {number[]} eight REFc Ucodes, 0..127
 *   ucodes   {number[]} N training-symbol Ucodes, one per segment, in order
 */
function buildDIL({ n = 0, sp = [1], tp = [1], h = [], ref = [], ucodes = [] } = {}) {
  const lsp = sp.length, ltp = tp.length;
  if (n < 0 || n > 255) throw new Error(`DIL N out of range: ${n}`);
  if (lsp < 1 || lsp > 128) throw new Error(`DIL L_SP out of range: ${lsp}`);
  if (ltp < 1 || ltp > 128) throw new Error(`DIL L_TP out of range: ${ltp}`);
  if (h.length !== 8 || ref.length !== 8) throw new Error('DIL needs eight H and eight REF');
  if (ucodes.length !== n) throw new Error(`DIL needs ${n} training Ucodes, got ${ucodes.length}`);

  const alpha = dilAlpha(lsp), beta = dilBeta(lsp, ltp);
  const len = dilLength(lsp, ltp, n);
  const starts = dilStartBits(len);
  const bits = BF.newSequence(len, starts);

  BF.putUInt(bits, 18, 25, n);
  // 26:33 reserved 0
  BF.putUInt(bits, 35, 41, lsp - 1);
  // 42 reserved 0
  BF.putUInt(bits, 43, 49, ltp - 1);
  // 50 reserved 0

  // SP from 52, TP from 52+α, both in 16-bit instalments that skip the start
  // bit at the head of each group. Padded with zeroes to the next multiple of
  // 16, which is what α and β already account for.
  const putPattern = (base, pat) => {
    for (let i = 0; i < pat.length; i++) {
      const group = Math.floor(i / 16), off = i % 16;
      bits[base + group * GROUP + off] = pat[i] ? 1 : 0;
    }
  };
  putPattern(52, sp);
  putPattern(52 + alpha, tp);

  // Eight H then eight REF, two per group: 7 bits then one reserved bit.
  const putPairs = (base, vals) => {
    for (let i = 0; i < vals.length; i++) {
      const group = Math.floor(i / 2), slot = i % 2;
      const lo = base + group * GROUP + slot * 8;
      BF.putUInt(bits, lo, lo + 6, vals[i]);
    }
  };
  putPairs(52 + beta, h);
  putPairs(120 + beta, ref);
  // The N training Ucodes follow in the same two-per-group shape from 188+β.
  putPairs(188 + beta, ucodes);

  const crcLo = 188 + beta + Math.ceil(n / 2) * GROUP;
  BF.putUInt(bits, crcLo, crcLo + 15,
    BF.crcOf(bits, starts, SYNC_BITS, crcLo));
  return bits;
}

function parseDIL(bits) {
  const sync = bits.slice(0, SYNC_BITS).every((b) => b === 1);
  const n = BF.getUInt(bits, 18, 25);
  const lsp = BF.getUInt(bits, 35, 41) + 1;
  const ltp = BF.getUInt(bits, 43, 49) + 1;
  const alpha = dilAlpha(lsp), beta = dilBeta(lsp, ltp);
  const getPattern = (base, count) => {
    const out = [];
    for (let i = 0; i < count; i++) {
      const group = Math.floor(i / 16), off = i % 16;
      out.push(bits[base + group * GROUP + off] ? 1 : 0);
    }
    return out;
  };
  const getPairs = (base, count) => {
    const out = [];
    for (let i = 0; i < count; i++) {
      const group = Math.floor(i / 2), slot = i % 2;
      const lo = base + group * GROUP + slot * 8;
      out.push(BF.getUInt(bits, lo, lo + 6));
    }
    return out;
  };
  const crcLo = 188 + beta + Math.ceil(n / 2) * GROUP;
  const starts = dilStartBits(dilLength(lsp, ltp, n));
  const crcOk = BF.getUInt(bits, crcLo, crcLo + 15) ===
    BF.crcOf(bits, starts, SYNC_BITS, crcLo);
  return {
    sync, crcOk, n, sp: getPattern(52, lsp), tp: getPattern(52 + alpha, ltp),
    h: getPairs(52 + beta, 8), ref: getPairs(120 + beta, 8),
    ucodes: getPairs(188 + beta, n),
  };
}

/**
 * The DIL as a list of segments, each already expanded to the Ucode and sign of
 * every symbol it contains. One pass over this is one repetition of the whole
 * sequence; §8.4.1 repeats the sequence, not the last segment.
 *
 * `uchordOf` maps a Ucode to its chord 1..8 — the Ucodes divide into eight
 * chords of sixteen, so chord = ⌊Ucode/16⌋ + 1, which is the same partition
 * V90Phase4's CP constellation masks use.
 */
const uchordOf = (ucode) => Math.floor(ucode / 16) + 1;

function dilSegments(desc) {
  const out = [];
  for (let s = 0; s < desc.n; s++) {
    const train = desc.ucodes[s];
    const c = uchordOf(train);
    const length = (desc.h[c - 1] + 1) * SYMS_PER_FRAME;
    const syms = new Array(length);
    for (let i = 0; i < length; i++) {
      // "The LSB of each pattern applies to the first symbol of a DIL-segment",
      // and each pattern repeats independently inside a longer segment.
      const sign = desc.sp[i % desc.sp.length] ? 1 : -1;
      const useTraining = desc.tp[i % desc.tp.length];
      syms[i] = { ucode: useTraining ? train : desc.ref[c - 1], sign };
    }
    out.push({ chord: c, ucode: train, length, syms });
  }
  return out;
}

/** Total symbols in one repetition of a descriptor's DIL. */
const dilSymbolCount = (desc) =>
  desc.ucodes.reduce((t, u) => t + (desc.h[uchordOf(u) - 1] + 1) * SYMS_PER_FRAME, 0);

module.exports = {
  U_INFO_MIN, U_INFO_MAX, uInfoValid, sdWUcode,
  TRN1D_MIN_SYMBOLS, JD_BITS, JD_START_BITS, jdRate, jdRateBit, JD_RATE_COUNT,
  buildJd, parseJd,
  dilAlpha, dilBeta, dilLength, dilStartBits, buildDIL, parseDIL,
  dilSegments, dilSymbolCount, uchordOf,
};
